using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.World;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class LandMaskIndexTests
{
    static JapanCatalog Catalog(){using var stream=typeof(ContinuousWorld).Assembly.GetManifestResourceStream("JapanTerrainMaskV1")!;using var memory=new MemoryStream();stream.CopyTo(memory);return JapanGeography.Read(memory.ToArray());}
    // Frozen pre-index ray caster; deliberately independent of the production index.
    static bool Ray(GeoCoordinate p,GeoCoordinate[] ring){bool inside=false;for(int i=0,j=ring.Length-1;i<ring.Length;j=i++){var a=ring[i];var b=ring[j];if((a.LatitudeE7>p.LatitudeE7)!=(b.LatitudeE7>p.LatitudeE7)&&p.LongitudeE7<(double)(b.LongitudeE7-a.LongitudeE7)*(p.LatitudeE7-a.LatitudeE7)/(b.LatitudeE7-a.LatitudeE7)+a.LongitudeE7)inside=!inside;}return inside;}
    static bool Legacy(GeoPolygon[] polygons,GeoCoordinate p)=>polygons.Any(poly=>Ray(p,poly.Outer)&&!poly.Holes.Any(h=>Ray(p,h)));
    static void CompareWorld(JapanCatalog catalog,LandMaskIndex index,GeoCoordinate geo){var projected=JapanGeography.Project(geo);var home=NationalRoutes.Nodes.Single(n=>n.Id=="castle").Position;var point=new FieldPoint(projected.EastMm-home.EastMm+5000,projected.NorthMm-home.NorthMm+5000);var world=FieldWorld.ToWorld(point);var roundtrip=JapanGeography.Inverse(new(world.EastMm,world.NorthMm));bool expected=Legacy(catalog.Polygons,roundtrip);Assert.Equal(expected,index.Contains(roundtrip));Assert.Equal(expected,ContinuousWorld.Land(point));}
    [Fact] public void PinnedVerticesAndNeighborsKeepOriginalBoundaryRules(){var c=Catalog();var index=new LandMaskIndex(c.Polygons);foreach(var polygon in c.Polygons)foreach(var ring in new[]{polygon.Outer}.Concat(polygon.Holes))for(int i=0;i<ring.Length;i+=Math.Max(1,ring.Length/64))foreach(int dy in new[]{-1,0,1})foreach(int dx in new[]{-1,0,1})CompareWorld(c,index,new(ring[i].LatitudeE7+dy,ring[i].LongitudeE7+dx));}
    [Fact] public void SeededNationwidePointsMatchFrozenRay(){var c=Catalog();var index=new LandMaskIndex(c.Polygons);var random=new Random(6413);for(int i=0;i<5000;i++)CompareWorld(c,index,new(random.Next(200000000,470000000),random.Next(1200000000,1500000000)));}
    static GeoPolygon Donut()=>new(new[]{new GeoCoordinate(-2000000,-2000000),new(-2000000,2000000),new(2000000,2000000),new(2000000,-2000000)},new[]{new[]{new GeoCoordinate(-1000000,-1000000),new(-1000000,1000000),new(1000000,1000000),new(1000000,-1000000)}});
    [Theory][InlineData(0,0,false)][InlineData(1500000,0,true)][InlineData(-1500000,0,true)][InlineData(0,2500000,false)][InlineData(-2000000,0,true)][InlineData(2000000,0,false)][InlineData(-1000000,0,false)][InlineData(1000000,0,true)]
    public void HoleAndNegativeLatitudeStripEdgesRetainHalfOpenRule(int lat,int lon,bool expected){var polygons=new[]{Donut()};var point=new GeoCoordinate(lat,lon);Assert.Equal(expected,Legacy(polygons,point));Assert.Equal(expected,new LandMaskIndex(polygons).Contains(point));}
    [Fact] public void DisjointAndConcaveShapesAgreeAcrossStripBoundaries(){var polygons=new[]{Donut(),new GeoPolygon(new[]{new GeoCoordinate(4000000,0),new(4000000,3000000),new(5000000,3000000),new(5000000,1000000),new(7000000,1000000),new(7000000,0)},Array.Empty<GeoCoordinate[]>())};var index=new LandMaskIndex(polygons);for(int y=-3000000;y<=8000000;y+=125000)for(int x=-3000000;x<=4000000;x+=125000){var point=new GeoCoordinate(y,x);Assert.Equal(Legacy(polygons,point),index.Contains(point));}Assert.True(index.Contains(new(4500000,2000000)));Assert.False(index.Contains(new(6000000,2000000)));}
    [Fact] public void FixedOriginMatchesCatalogWithoutAliasingCallerArrays(){var nodes=NationalRoutes.Nodes;var origin=nodes.Single(n=>n.Id=="castle").Position;int at=Array.FindIndex(nodes,n=>n.Id=="castle");nodes[at]=nodes[at] with{Position=new(origin.EastMm+999999,origin.NorthMm-999999)};foreach(var p in new[]{new FieldPoint(5000,5000),new(-123456789,987654321),new(1999999999,-1999999999)})Assert.Equal(new RoutePoint(origin.EastMm+p.X-5000,origin.NorthMm+p.Y-5000),FieldWorld.ToWorld(p));}
}
